# Initially generated by GitHub Copilot.
"""
Check that every Job chapter module and every RECORD_* assignment agree.

Checks per chapter module:
  1. The filename is exactly qr_CC.py and contains at least one record assignment.
  2. Every record assignment is a single RECORD_CCVV[_WORDID] dict literal.
  3. The chapter in every RECORD name matches the chapter module.
  4. A literal ``qr-cv`` matches the RECORD name. A record that inherits
     ``qr-cv`` must spread a same-verse ``RECORD_CCVV_CMN...`` binding.
  5. The WORDID suffix and literal ``qr-word-id`` value match; records without
     a suffix do not have ``qr-word-id``.

Checks over discovery:
  6. No file or RECORD name is discovered twice.
  7. Empty discovery fails.

Usage:
  python check_qr_consistency.py [path ...]
"""

import ast
import re
import sys
from collections import Counter, defaultdict
from pathlib import Path

import boj_paths


def check_file(filepath: Path) -> tuple[list[str], list[str]]:
    """Return the record names and violations found in one chapter module."""
    source = filepath.read_text(encoding="utf-8")
    try:
        tree = ast.parse(source, filename=str(filepath))
    except SyntaxError as exc:
        return [], [f"  SyntaxError: {exc}"]

    try:
        module_chapter = _parse_chapter_stem(filepath.stem)
    except ValueError as exc:
        return [], [f"  Bad filename: {exc}"]

    record_names = []
    violations = []
    for node in ast.iter_child_nodes(tree):
        if isinstance(node, ast.Assign):
            targets = [
                target.id
                for target in node.targets
                if isinstance(target, ast.Name) and target.id.startswith("RECORD_")
            ]
            if not targets:
                continue
            record_names.extend(targets)
            if len(node.targets) != 1 or len(targets) != 1:
                violations.append(
                    f"  Line {node.lineno}: RECORD assignment must have one name target"
                )
                continue
            if not isinstance(node.value, ast.Dict):
                violations.append(
                    f"  Line {node.lineno}: {targets[0]} is not assigned a dict literal"
                )
                continue
            violations.extend(
                _check_record(module_chapter, targets[0], node.value, node.lineno)
            )
        elif (
            isinstance(node, ast.AnnAssign)
            and isinstance(node.target, ast.Name)
            and node.target.id.startswith("RECORD_")
        ):
            record_names.append(node.target.id)
            violations.append(
                f"  Line {node.lineno}: {node.target.id} must use a plain dict assignment"
            )

    if not record_names:
        violations.append("  No RECORD_* assignment found")
    return record_names, violations


def main(argv=None):
    args = sys.argv[1:] if argv is None else argv
    paths = [Path(value) for value in args] if args else [boj_paths.qr_package_dir()]

    files_to_check = []
    discovery_violations = []
    for path in paths:
        if path.is_file() and path.suffix == ".py" and path.stem.startswith("qr_"):
            files_to_check.append(path)
        elif path.is_dir():
            files_to_check.extend(sorted(path.glob("qr_*.py")))
        else:
            discovery_violations.append(f"No qr_*.py source at {path}")

    duplicate_paths = [
        path
        for path, count in Counter(path.resolve() for path in files_to_check).items()
        if count > 1
    ]
    discovery_violations.extend(
        f"Chapter module discovered more than once: {path}" for path in duplicate_paths
    )
    if not files_to_check:
        discovery_violations.append("No qr_*.py chapter modules discovered")

    total_violations = len(discovery_violations)
    for violation in discovery_violations:
        print(violation)

    record_paths = defaultdict(list)
    for filepath in sorted(set(files_to_check)):
        record_names, violations = check_file(filepath)
        for record_name in record_names:
            record_paths[record_name].append(filepath)
        if violations:
            print(f"{filepath}:")
            for violation in violations:
                print(violation)
            total_violations += len(violations)

    for record_name, filepaths in sorted(record_paths.items()):
        if len(filepaths) <= 1:
            continue
        print(
            f"Duplicate {record_name}: "
            + ", ".join(str(filepath) for filepath in filepaths)
        )
        total_violations += 1

    if total_violations:
        print(f"\nFound {total_violations} violation(s).")
        return 1
    print(
        f"No qr consistency violations found "
        f"({len(files_to_check)} chapter modules, {len(record_paths)} records checked)."
    )
    return 0


def _check_record(
    module_chapter: str, record_name: str, record_dict: ast.Dict, line: int
) -> list[str]:
    try:
        record_ccvv, record_word_id = _parse_qr_tag(record_name, "RECORD_")
    except ValueError as exc:
        return [f"  Line {line}: bad RECORD name: {exc}"]

    violations = []
    record_chapter = record_ccvv[:2]
    if module_chapter != record_chapter:
        violations.append(
            f"  Line {line}: chapter mismatch: filename has {module_chapter}, "
            f"RECORD has {record_chapter}"
        )

    cv_values = _values_for_key(record_dict, "qr-cv")
    if len(cv_values) > 1:
        violations.append(f"  Line {line}: duplicate 'qr-cv' keys")
    elif cv_values:
        dict_cv = _literal_str(cv_values[0])
        expected_cv = _ccvv_to_cv(record_ccvv)
        if dict_cv is None:
            violations.append(f"  Line {line}: 'qr-cv' must be a string literal")
        elif dict_cv != expected_cv:
            violations.append(
                f"  Line {line}: qr-cv mismatch: RECORD implies {expected_cv!r}, "
                f"dict has {dict_cv!r}"
            )
    else:
        spread_ccvvs = _spread_record_ccvvs(record_dict)
        if spread_ccvvs != [record_ccvv]:
            violations.append(
                f"  Line {line}: no literal 'qr-cv'; expected one same-verse "
                f"RECORD_{record_ccvv}_CMN... spread, found {spread_ccvvs}"
            )

    word_id_values = _values_for_key(record_dict, "qr-word-id")
    if len(word_id_values) > 1:
        violations.append(f"  Line {line}: duplicate 'qr-word-id' keys")
    elif word_id_values:
        dict_word_id = _literal_str(word_id_values[0])
        if dict_word_id is None:
            violations.append(f"  Line {line}: 'qr-word-id' must be a string literal")
        elif record_word_id is None:
            violations.append(
                f"  Line {line}: RECORD has no WORDID suffix but dict has "
                f"'qr-word-id': {dict_word_id!r}"
            )
        elif dict_word_id != record_word_id:
            violations.append(
                f"  Line {line}: WORDID mismatch: RECORD has {record_word_id!r}, "
                f"dict has {dict_word_id!r}"
            )
    elif record_word_id is not None:
        violations.append(
            f"  Line {line}: RECORD has WORDID {record_word_id!r} "
            f"but dict lacks 'qr-word-id'"
        )
    return violations


def _ccvv_to_cv(ccvv: str) -> str:
    """Convert CCVV like ``0816`` to qr-cv format like ``8:16``."""
    return f"{int(ccvv[:2])}:{int(ccvv[2:])}"


def _parse_chapter_stem(stem: str) -> str:
    match = re.fullmatch(r"qr_(\d{2})", stem)
    if match is None:
        raise ValueError(f"expected 'qr_CC.py', got {stem + '.py'!r}")
    chapter = int(match.group(1))
    if not 1 <= chapter <= 42:
        raise ValueError(f"chapter is outside Job: {match.group(1)}")
    return match.group(1)


def _parse_qr_tag(tag: str, prefix: str) -> tuple[str, str | None]:
    if not tag.startswith(prefix):
        raise ValueError(f"expected prefix {prefix!r} in {tag!r}")
    match = re.fullmatch(r"(\d{2})(\d{2})(?:_([A-Za-z0-9_]+))?", tag[len(prefix) :])
    if match is None:
        raise ValueError(f"expected CCVV[_WORDID] after {prefix!r}, got {tag!r}")
    chapter, verse, word_id = match.groups()
    if not 1 <= int(chapter) <= 42:
        raise ValueError(f"chapter is outside Job: {chapter}")
    if int(verse) < 1:
        raise ValueError(f"verse must be positive: {verse}")
    return chapter + verse, word_id


def _values_for_key(dict_node: ast.Dict, key_name: str) -> list[ast.AST]:
    return [
        value
        for key, value in zip(dict_node.keys, dict_node.values)
        if isinstance(key, ast.Constant) and key.value == key_name
    ]


def _literal_str(node: ast.AST) -> str | None:
    if isinstance(node, ast.Constant) and isinstance(node.value, str):
        return node.value
    return None


def _spread_record_ccvvs(dict_node: ast.Dict) -> list[str]:
    ccvvs = []
    for key, value in zip(dict_node.keys, dict_node.values):
        if key is not None or not isinstance(value, ast.Name):
            continue
        try:
            ccvv, word_id = _parse_qr_tag(value.id, "RECORD_")
        except ValueError:
            continue
        if word_id is not None and word_id.startswith("CMN"):
            ccvvs.append(ccvv)
    return ccvvs


if __name__ == "__main__":
    sys.exit(main())
